engine.buildAskEliPrompt:
function buildAskEliPrompt(input) {
  var CAP = 20;
  var question = String(input.question || "").trim();
  var docText = String(input.docText || "");
  var selectionText = String(input.selectionText || "").trim();
  var attachmentPrefix = String(input.attachmentPrefix || "");
  var history = Array.isArray(input.history) ? input.history : [];
  var modifyMode = !!input.modifyMode;
  var hasRedlines = !!input.hasRedlines;
  var roster = input.roster || null;
  var useAnchors = !!input.useAnchors;
  var currentUserName = String(input.currentUserName || "Andrew");

  // History block — last 10 turns max. Plain text, no JSON/HTML.
  var historyBlock = "";
  if (history.length) {
    historyBlock = history.slice(-CAP).map(function (turn) {
      var role = turn.role === "model" ? "ELI" : "User";
      return role + ": " + String(turn.content || "");
    }).join("\n");
  }

  // Selection-aware mode block. FROM v2 qaModeTargetSelection.
  var modeBlock = "";
  if (selectionText && selectionText.length > 4) {
    modeBlock =
      "\n    CONTEXTUAL ANALYSIS RULE:\n" +
      "    - The user has highlighted a specific section (TARGET SELECTION).\n" +
      "    - Focus your answer on that selection.\n" +
      "    - HOWEVER, you MUST cross-reference the FULL DOCUMENT CONTEXT to check for definitions, conflicting clauses, or overriding terms that affect the selection.\n";
  }

  // Always-broad mode — falls back to general legal knowledge when the
  // doc doesn't contain the answer. FROM v2 qaModeBroad.
  var broadBlock =
    "\n    MODE: BROAD / CONSULTANT\n" +
    "    - Base your facts on the document.\n" +
    "    - If the user asks for opinions, explanations, or 'market standards' that are not in the file, USE YOUR GENERAL KNOWLEDGE to answer helpfully.\n" +
    "    - FORMATTING: Use HTML tags for structure (<b>bold</b>, <ul><li>lists</li></ul>, <br> breaks).\n";

  // Author roster block — only when redlines present + roster provided.
  // FROM v2 qaAuthorRoster + qaRedlineNote.
  var rosterBlock = "";
  if (hasRedlines && roster && typeof roster === "object") {
    var internal = [], external = [], unknown = [];
    Object.keys(roster).forEach(function (name) {
      var side = String(roster[name] || "").toLowerCase();
      if (side === "internal") internal.push(name);
      else if (side === "external") external.push(name);
      else unknown.push(name);
    });
    var firstUnknown = unknown[0] || "";
    rosterBlock =
      "\n\n    CONFIRMED AUTHOR ROSTER (USER-VERIFIED GROUND TRUTH — TRUST THIS OVER ANY HEURISTIC):\n" +
      "    - INTERNAL / Colgate side: " + (internal.join(", ") || "(none)") + "\n" +
      "    - EXTERNAL / Counterparty side: " + (external.join(", ") || "(none)") + "\n" +
      "    - UNKNOWN side: " + (unknown.join(", ") || "(none)") + "\n" +
      "    Use these classifications verbatim. For UNKNOWN authors, refer by name without claiming a side. " +
      (firstUnknown ? "(e.g. \"" + firstUnknown + " inserted...\")" : "") + "\n";
  }
  var redlineNote = hasRedlines
    ? ("\n    REDLINE NOTE: This document contains tracked changes. Edits are marked inline as " +
       "[INSERTED by Author: text], [DELETED by Author: text], [MOVED FROM by Author: text], or " +
       "[MOVED TO by Author: text]. The current Colgate user is \"" + currentUserName + "\". " +
       "Use \"you\"/\"your\" ONLY for edits whose author matches the current user. For other internal " +
       "edits, name the colleague (e.g. \"Your colleague X inserted...\"). For external edits, identify " +
       "the counterparty by name. Do NOT include bracket markers in your answer text — describe naturally." +
       rosterBlock + "\n")
    : "";

  // Modify-mode task instruction. FROM v2 qaTaskModification.
  var taskBlock;
  // CITATION FORMAT — when useAnchors is true, citations are returned as
  // OBJECTS with id (matching the JSON paragraph-array's id) so the
  // frontend can jump precisely. Falls back to plain strings when
  // anchors aren't available (e.g. attached-only path).
  var citeShape = useAnchors
    ? "{ \"id\": \"ELI_QA_<N>\", \"text\": \"verbatim or near-verbatim excerpt for [1]\" }"
    : "\"verbatim excerpt for [1]\"";
  var citeIdRule = useAnchors
    ? "    - Each citation's 'id' MUST be the EXACT id from the paragraph-indexed JSON above (e.g. 'ELI_QA_42'). The id is what makes the [N] pin clickable — without it the pin can't jump to the paragraph.\n"
    : "";

  if (modifyMode) {
    taskBlock =
      "TASK: You may MODIFY the document. If the user is asking to change/rewrite/strengthen/draft a specific clause, return RAW JSON:\n" +
      "    {\n" +
      "      \"action\": \"replace_text\",\n" +
      "      \"target_original\": \"EXACT_VERBATIM_STRING_FROM_DOCUMENT_TO_REPLACE\",\n" +
      "      \"proposed_new\": \"YOUR_STRONGER_OR_NEW_TEXT\",\n" +
      "      \"explanation\": \"Short summary of what changed and why.\"\n" +
      "    }\n" +
      "    HEADER RULE: INCLUDE manually-typed section headers (e.g. \"5.3 Liability:\", \"Indemnification.\") in target_original AND in proposed_new — the surgical rebuilder preserves their formatting per-word and the diff treats unchanged tokens as equals. EXCLUDE auto-generated list numbering that Word's auto-numbered list inserts dynamically (those don't appear in the searchable text). When in doubt, include the header — apply will still work because the rebuilder anchors on the surrounding words.\n" +
      "    If the user is NOT asking to modify a specific string, fall back to the standard answer shape:\n" +
      "    { \"answer\": \"<HTML answer with [N] markers>\", \"citations\": [" + citeShape + ", ...], \"followups\": [\"4-8 word user command 1\", \"4-8 word user command 2\"] }\n" +
      citeIdRule;
  } else {
    // Standard answer task. FROM v2 qaTaskStandard.
    taskBlock =
      "TASK: Return RAW JSON (no markdown, no preamble):\n" +
      "    { \"answer\": \"<HTML answer with [N] markers inline next to claims>\", \"citations\": [" + citeShape + ", " + citeShape + "], \"followups\": [\"4-8 word user command 1\", \"4-8 word user command 2\"] }\n" +
      "    INLINE CITATION RULE:\n" +
      "    - Every entry in 'citations' MUST have a matching [N] marker placed INLINE in 'answer', adjacent to the claim it supports.\n" +
      "    - Number of [N] markers MUST equal length of citations array.\n" +
      "    - Cite generously: every factual claim that came from the document deserves a citation. Prefer verbatim text but a near-verbatim excerpt of the sentence the AI is referencing is also acceptable. The pin lets the user jump to the source — silent omission is worse than an approximate citation.\n" +
      "    ⚠️ CRITICAL — INLINE MARKER vs PARAGRAPH ID: The [N] inline marker in 'answer' is the 1-based INDEX into the citations array — [1] for the first citation, [2] for the second, [3] for the third, etc. It is NOT the paragraph id from the JSON. Even if a citation's id is 'ELI_QA_64', the inline marker for it is still [1] if it's the first entry in citations[]. Using paragraph numbers like [64] inline will silently break the pin rendering.\n" +
      "    WRONG: answer says \"...IP is fragmented [64]...\" because the cited paragraph is ELI_QA_64.\n" +
      "    RIGHT: answer says \"...IP is fragmented [1]...\" because that's the first citation in the citations array (whose id is ELI_QA_64).\n" +
      citeIdRule +
      "    'followups' must contain EXACTLY 2 concise actionable commands (4-8 words each) written from the user's perspective (e.g. \"Draft a mutual version\", \"Explain the key risks\"), NOT questions from you.\n";
  }

  // Selection block — verbatim text the user highlighted, capped at 4000
  // chars to keep prompt size sane.
  var selectionBlock = (selectionText && selectionText.length > 4)
    ? ("\n    TARGET SELECTION (USER HIGHLIGHTED):\n    \"\"\"\n    " + selectionText.substring(0, 4000) + "\n    \"\"\"\n")
    : "";

  // Document text — trimmed to 200K chars. When useAnchors is true, the
  // docText already has _ELI_QA_<id> anchors embedded by getQaAnchorPayload.
  var docHeader = useAnchors
    ? "    LIVE WORD DOCUMENT (FULL CONTEXT, paragraph-indexed JSON — each entry: id, text, and section):\n"
    : "    LIVE WORD DOCUMENT (FULL CONTEXT):\n";
  var docBlock = docText
    ? (docHeader + "    " + docText.substring(0, 500000) + "\n")
    : "    (No document text available.)\n";

  // Section context rule — the paragraph-indexed payload's entries carry
  // a 'section' field from the kernel structural map (the same section
  // mapping error_review uses). Tells the model to anchor answers to the
  // document's real structure rather than treating it as a flat blob.
  var sectionRule = useAnchors
    ? "\n    SECTION CONTEXT: Each paragraph object may carry a 'section' field — the document section/article it sits in (e.g. \"Article V › §5.3 Indemnification\"). When present, use it to:\n" +
      "    - Anchor every answer to the document's real structure: name the section a clause lives in (\"§5.3 Indemnification caps liability at...\"), don't just quote loose text.\n" +
      "    - Reason ACROSS sections: a defined term, cap, carve-out, or cross-reference in one section that affects another.\n" +
      "    - Tell the user WHERE in the agreement something is, by section number, so they can navigate there.\n"
    : "";

  // Final assembly. attachmentPrefix is prepended (e.g. for "both" scope
  // or attached-only). It's already shaped with `=== ATTACHED FILE ===`
  // headers by buildAttachmentPrefix.
  return [
    "You are 'ELI', an AI legal assistant for Colgate-Palmolive's legal team.",
    "    PERSPECTIVE: The user asking is ALWAYS a Colgate lawyer reviewing this agreement from Colgate's side.",
    "    When the user says 'we', 'us', or 'our', they mean Colgate. Treat the other party as the counterparty.",
    historyBlock ? "    CONVERSATION SO FAR:\n" + historyBlock : "",
    "    CURRENT QUESTION: " + question,
    selectionBlock,
    attachmentPrefix ? "    " + attachmentPrefix : "",
    docBlock,
    sectionRule,
    modeBlock + broadBlock + redlineNote,
    taskBlock,
  ].filter(Boolean).join("\n");
}

// FROM v2 _isTranslateRequest. Cheap regex; init checks before sending
// to AI and routes through a separate prompt path.

engine.isTranslateRequest:
function isTranslateRequest(question) {
  if (!question) return false;
  var s = String(question);
  return /\btranslate(d|s|ing)?\b/i.test(s) || /\btranslation\b/i.test(s);
}

// Translate prompt builder. Two variants: HTML (when selection contains
// tables) preserves table markup; text strips to plain. FROM v2 lines
// 11260-11328.

engine.buildTranslatePrompt:
function buildTranslatePrompt(input) {
  var question = String(input.question || "").trim();
  var sourceText = String(input.sourceText || "").trim();
  var sourceHtml = String(input.sourceHtml || "").trim();
  var hasTables = /<table[\s>]/i.test(sourceHtml);
  if (hasTables) {
    return [
      "You are a legal translator.",
      "TASK: " + question,
      "Preserve all HTML table markup (<table>, <tr>, <td>, <th>) — translate ONLY the text content inside.",
      "Return RAW JSON: { \"hasTables\": true, \"html\": \"<the translated HTML>\" }",
      "",
      "SOURCE HTML:",
      sourceHtml.substring(0, 100000),
    ].join("\n");
  }
  return [
    "You are a legal translator.",
    "TASK: " + question,
    "Return RAW JSON: { \"hasTables\": false, \"text\": \"<the translated plain text>\" }",
    "",
    "SOURCE TEXT:",
    sourceText.substring(0, 100000),
  ].join("\n");
}

// Build the attachment prefix for the standard prompt. FROM v2
// _buildAttachmentPrefix (line 11352). Concatenates active template payload,
// attached-text file payload, and PDF marker (the actual PDF bytes flow as
// inlineData in the AI call, not in the text prefix).

engine.buildAttachmentPrefix:
function buildAttachmentPrefix(input) {
  var pre = "";
  if (input.activeTemplatePayload) pre += String(input.activeTemplatePayload) + "\n";
  if (input.attachedText) {
    var name = input.attachedName || "document";
    var text = String(input.attachedText).substring(0, 500000);
    pre += '=== ATTACHED FILE (' + name + ') ===\n"""\n' + text + '\n"""\n';
  }
  if (input.attachedPdfMarker) {
    var pdfName = input.attachedName || "document";
    pre += '=== ATTACHED PDF (' + pdfName + ') ===\n(Content provided as inline PDF data below)\n';
  }
  return pre;
}

// ─── AI response parsing ─────────────────────────────────────────────

// Robust JSON-extract from Gemini response. FROM v2 tryParseGeminiJSON.
// AI sometimes wraps JSON in ```json fences or adds preamble; strip and
// try to parse. Return parsed object OR `{answer: "<raw text>"}` fallback.

engine.parseAiResponse:
function parseAiResponse(raw) {
  if (raw == null) return { answer: "" };
  var s = String(raw).trim();
  // Strip ```json … ``` fences.
  s = s.replace(/^```(?:json|html)?\s*/i, "").replace(/```\s*$/, "").trim();
  // Try direct parse.
  try {
    var direct = JSON.parse(s);
    if (direct && typeof direct === "object") return direct;
  } catch (e) { /* fall through */ }
  // Find first { and last } — Gemini often wraps JSON in chatter.
  var first = s.indexOf("{"), last = s.lastIndexOf("}");
  if (first !== -1 && last > first) {
    try {
      var sliced = JSON.parse(s.slice(first, last + 1));
      if (sliced && typeof sliced === "object") return sliced;
    } catch (e) { /* fall through */ }
  }
  // Plain HTML fallback.
  return { answer: s };
}

// ─── History capping ─────────────────────────────────────────────────

// Cap history to prevent prompt bloat. FROM v2 chatHistory.push override.

engine.capHistory:
function capHistory(history) {
  var CAP = 20;
  if (!Array.isArray(history)) return [];
  if (history.length <= CAP) return history.slice();
  return history.slice(history.length - CAP);
}

// ─── Citation rendering ──────────────────────────────────────────────

// Walks `[N]` markers in the answer HTML and replaces them with citation
// chip placeholders that init wires up to actual click handlers.
// Returns { html, count } so the view can decide whether to show a
// citations footer if any [N] is unmatched. FROM v2 addChatBubble citation
// loop (line 11809).

engine.renderCitations:
function renderCitations(answerHtml, citations) {
  var html = String(answerHtml || "");
  if (!Array.isArray(citations) || !citations.length) {
    return { html: html, count: 0 };
  }
  var matched = 0;
  // Build an id→index map for the paragraph-id fallback. The AI
  // occasionally puts the paragraph_id inline (e.g. [64] when the cited
  // chunk is ELI_QA_64) instead of the 1-based citation index. We
  // recover by checking if `N` matches the numeric suffix of a citation's
  // id. This restores the pin instead of leaving raw [66] text.
  var idSuffixToIdx = {};
  citations.forEach(function (c, i) {
    if (c && typeof c === "object" && c.id) {
      var m = String(c.id).match(/(\d+)$/);
      if (m) idSuffixToIdx[m[1]] = i;
    }
  });
  // Replace each [N] with a chip wrapped in a group span. Wrapping the
  // chip + its LEADING whitespace inside `_eli3_chat_cite_group` lets
  // the "hide pins" toggle remove BOTH together via one CSS rule —
  // otherwise the leading space stays and produces " ." (extra space
  // before the sentence's period) every time pins are off.
  // Trailing punctuation stays OUTSIDE the group so periods/commas
  // remain on screen when pins are hidden. Trailing whitespace also
  // stays outside so the gap between sentences reads naturally.
  var chipped = html.replace(/(\s*)\[(\d+)\](\s*)([.,;:!?\)\]])?/g, function (full, lead, n, trail, punct) {
    var idx = parseInt(n, 10) - 1;
    if (idx < 0 || idx >= citations.length) {
      if (idSuffixToIdx.hasOwnProperty(n)) {
        idx = idSuffixToIdx[n];
      } else {
        return full;
      }
    }
    matched++;
    var c = citations[idx] || {};
    var cText = (typeof c === "string") ? c : (c.text || c.excerpt || "");
    var cId = (typeof c === "object" && c.id) ? c.id : "";
    var cleanText = String(cText).replace(/"/g, "&quot;").replace(/'/g, "&#39;");
    return '<span class="_eli3_chat_cite_group">' +
      (lead || "") +
      '<span class="_eli3_chat_cite" data-cite-n="' + (idx + 1) + '" data-cite-id="' + cId + '" ' +
      'data-cite-text="' + cleanText + '" title="Click to locate in document">📍</span>' +
      '</span>' +
      (punct || "") + (trail || "");
  });
  return { html: chipped, count: matched, total: citations.length };
}

// ─── DOCX cruft strip — FROM v2 getCleanTextAndContext (line 13021) ──
// Strips comment nodes / del-spans / page-numbers / [abc12] markers from
// HTML and returns clean text + a "deletedPhrases" context note for the
// AI prompt. Used when v3's body.text isn't enough (e.g. when the user
// has drafted then deleted text — AI should know what was just removed).

engine.cleanDocHtml:
function cleanDocHtml(html) {
  if (!html) return { text: "", context: "" };
  if (typeof DOMParser === "undefined") return { text: String(html).replace(/<[^>]+>/g, " "), context: "" };
  var parser = new DOMParser();
  var doc = parser.parseFromString(html, "text/html");
  var delNodes = doc.querySelectorAll(
    "del, s, strike, span[style*='line-through'], span[style*='text-decoration:line-through'], span[style*='text-decoration: line-through']"
  );
  var deletedPhrases = [];
  delNodes.forEach(function (node) {
    var txt = (node.textContent || "").trim();
    if (txt.length > 3) deletedPhrases.push(txt);
    node.remove();
  });
  var commentNodes = doc.querySelectorAll(
    "div[style*='mso-element:comment'], .CommentText, .msocommentanchor, span.msocomanchor, " +
    "a[name*='_msocom_'], a[id*='_com_'], a[name*='_com_'], " +
    "[class*='comment' i], [id*='comment' i], [name*='comment' i], .MsoCommentText, .MsoCommentReference"
  );
  commentNodes.forEach(function (n) { n.remove(); });
  var brs = doc.querySelectorAll("br");
  brs.forEach(function (br) { br.replaceWith("\n"); });
  var tempDiv = document.createElement("div");
  tempDiv.innerHTML = doc.body.innerHTML;
  var cleanText = tempDiv.innerText || tempDiv.textContent || "";
  cleanText = cleanText.replace(/\n\s*\n/g, "\n").trim();
  cleanText = cleanText.replace(/Page\s+\d+\s+(of\s+\d+)?/gi, " ");
  cleanText = cleanText.replace(/\[[a-zA-Z]{1,4}\d{1,3}\]/g, " ");
  cleanText = cleanText.replace(/\[Comment\s*\d*\]/gi, " ");
  cleanText = cleanText.replace(/\[[a-zA-Z]{1,4}\s+comment\s*\d*\]/gi, " ");
  var contextMsg = "";
  if (deletedPhrases.length > 0) {
    var unique = deletedPhrases.filter(function (v, i, a) { return a.indexOf(v) === i; }).slice(0, 5);
    contextMsg = "NOTE: The user recently deleted these phrases: [" + unique.join(", ") + "]";
  }
  return { text: cleanText, context: contextMsg, deletedPhrases: deletedPhrases };
}

// ─── Redline OOXML parsing — FROM v2 _markRedlinesInOoxml (line 19911) ─
// Walks raw OOXML body, replaces each <w:ins> / <w:del> / <w:moveFrom> /
// <w:moveTo> with a `[INSERTED by Author: text]` style marker, returns
// {text, hasRedlines, authors} for the prompt builder. Pure string ops.

engine.markRedlinesInOoxml:
function markRedlinesInOoxml(raw, maxChars) {
  if (!raw) return { text: "", hasRedlines: false, authors: [] };
  var hasRedlines = /<w:(ins|del|moveFrom|moveTo)\b/.test(raw);
  if (!hasRedlines) return { text: "", hasRedlines: false, authors: [] };
  var authorsSet = Object.create(null);
  function _innerText(inner) {
    var matches = inner.match(/<w:(?:t|delText)[^>]*>([\s\S]*?)<\/w:(?:t|delText)>/g) || [];
    return matches.map(function (m) { return m.replace(/<[^>]+>/g, ""); }).join("").replace(/\s+/g, " ").trim();
  }
  function _author(openTag) {
    var m = openTag.match(/\bw:author=(?:"([^"]*)"|'([^']*)')/);
    var name = (m && (m[1] || m[2])) || "";
    if (name) authorsSet[name] = true;
    return name;
  }
  function _marker(label, author, content) {
    var who = author ? " by " + author : "";
    return "<w:t>[" + label + who + ": " + content + "]</w:t>";
  }
  raw = raw.replace(/(<w:del\b[^>]*>)([\s\S]*?)<\/w:del>/g, function (_, openTag, inner) {
    var t = _innerText(inner);
    return t ? _marker("DELETED", _author(openTag), t) : "";
  });
  raw = raw.replace(/<w:del\b[^>]*\/>/g, "");
  raw = raw.replace(/(<w:ins\b[^>]*>)([\s\S]*?)<\/w:ins>/g, function (_, openTag, inner) {
    var t = _innerText(inner);
    return t ? _marker("INSERTED", _author(openTag), t) : "";
  });
  raw = raw.replace(/(<w:moveFrom\b[^>]*>)([\s\S]*?)<\/w:moveFrom>/g, function (_, openTag, inner) {
    var t = _innerText(inner);
    return t ? _marker("MOVED FROM", _author(openTag), t) : "";
  });
  raw = raw.replace(/(<w:moveTo\b[^>]*>)([\s\S]*?)<\/w:moveTo>/g, function (_, openTag, inner) {
    var t = _innerText(inner);
    return t ? _marker("MOVED TO", _author(openTag), t) : "";
  });
  var matches = raw.match(/<w:t[^>]*>([\s\S]*?)<\/w:t>/g) || [];
  var text = matches.map(function (m) { return m.replace(/<[^>]+>/g, ""); }).join(" ")
    .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
    .replace(/\s+/g, " ").trim();
  if (maxChars && text.length > maxChars) text = text.substring(0, maxChars);
  return { text: text, hasRedlines: true, authors: Object.keys(authorsSet) };
}

// ─── Author classification (heuristic) ──────────────────────────────
// Domain-based shortcut: colpal / colgate / hills → internal. Anything
// else → external. Far simpler than v2's modal, but matches the
// ground-truth roster from the prompt's perspective for ~95% of cases.
// Returns { name: "internal"|"external" } map.

engine.classifyAuthorsHeuristic:
function classifyAuthorsHeuristic(authors) {
  var roster = {};
  if (!Array.isArray(authors)) return roster;
  authors.forEach(function (name) {
    if (!name || typeof name !== "string") return;
    var lower = name.toLowerCase();
    var isInternal =
      /colpal|colgate|hills|hill's|hill\sb|hill\sa/.test(lower) ||
      /@(colpal|colgate|hills)\.com/i.test(name);
    roster[name] = isInternal ? "internal" : "external";
  });
  return roster;
}

// ─── Word-level diff (jsdiff) — used by surgical redline rebuilder ──
// EXACT v2 port (taskpane_v2.js:18182). Tokenize via /\S+/g (words
// ONLY, no whitespace tokens) and use the jsdiff library on
// window.Diff (loaded from Script Lab Library tab — same CDN URL as
// v2: cdnjs.cloudflare.com/.../jsdiff/5.1.0/diff.min.js).
//
// CRITICAL: keeping whitespace tokens in the input — like the prior
// custom DP did — produces single-space "change" hunks that render as
// red+green noise and break the rebuilder's per-word format snapshot.
// v2 strips whitespace before diffing and re-emits a single space
// between equal hunks at render time.
//
// Hunk shape (v2-faithful):
//   {type:"equal",  text:"<single word>"}
//   {type:"change", oldWords:[...], newWords:[...], id:"hunk_<n>"}
// Only TWO types — adds + removes coalesce into change hunks during
// the forEach pass. The downstream rebuilder (_surgicalRedlineApply)
// already handles change hunks with empty oldWords or newWords for
// pure-insert / pure-delete regions, so this stays compatible.

engine.computeWordDiff:
function computeWordDiff(oldText, newText) {
  if (!oldText) oldText = "";
  if (!newText) newText = "";
  if (typeof Diff === "undefined" || typeof Diff.diffArrays !== "function") {
    return oldText === newText
      ? [{ type: "equal", text: oldText }]
      : [{
          type: "change",
          oldWords: oldText.split(/\s+/).filter(Boolean),
          newWords: newText.split(/\s+/).filter(Boolean),
          id: "hunk_0",
        }];
  }
  var oldTokens = oldText.match(/\S+/g) || [];
  var newTokens = newText.match(/\S+/g) || [];
  var parts = Diff.diffArrays(oldTokens, newTokens);
  var hunks = [];
  var currentHunk = null;
  parts.forEach(function (p) {
    if (!p.added && !p.removed) {
      if (currentHunk) { hunks.push(currentHunk); currentHunk = null; }
      p.value.forEach(function (w) { hunks.push({ type: "equal", text: w }); });
    } else {
      if (!currentHunk) currentHunk = { type: "change", oldWords: [], newWords: [], id: "hunk_" + hunks.length };
      if (p.removed) p.value.forEach(function (w) { currentHunk.oldWords.push(w); });
      if (p.added)   p.value.forEach(function (w) { currentHunk.newWords.push(w); });
    }
  });
  if (currentHunk) hunks.push(currentHunk);
  return hunks;
}

// ─── Markdown-lite ───────────────────────────────────────────────────

// FROM v2 addChatBubble plain-text branch — converts **bold**, *italic*,
// and \n to HTML when the caller passes raw text rather than HTML. Used
// for user bubbles + activity-feed restoration.

engine.markdownLite:
function markdownLite(text) {
  var s = String(text == null ? "" : text);
  // Escape first.
  s = s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  // Bold
  s = s.replace(/\*\*([^*]+)\*\*/g, "<b>$1</b>");
  // Italic (single asterisks not adjacent to bold)
  s = s.replace(/(^|[^*])\*([^*]+)\*([^*]|$)/g, "$1<i>$2</i>$3");
  // Newlines
  s = s.replace(/\n/g, "<br>");
  return s;
}

// ─── Engine entry ────────────────────────────────────────────────────

// Build the prompt, call AI, parse the response, return both the parsed
// shape (action/answer/citations/followups) and the new history. Per
// evalBundle isolation, sibling helpers come in via providers.

engine.analyze:
function analyze(input, providers) {
  var ai = providers && providers.ai;
  if (!ai || typeof ai.complete !== "function") {
    return Promise.reject(new Error("ask_eli: providers.ai.complete missing"));
  }
  var buildPrompt = providers && providers.buildPrompt;
  var capHist     = providers && providers.capHistory;
  var parseAi     = providers && providers.parseAiResponse;
  if (typeof buildPrompt !== "function" || typeof capHist !== "function" || typeof parseAi !== "function") {
    return Promise.reject(new Error("ask_eli: providers.buildPrompt + capHistory + parseAiResponse required"));
  }

  var prompt = buildPrompt(input);
  var aiOpts = {};
  if (input.signal) aiOpts.signal = input.signal;
  // PDF inline data (Gemini multimodal). Passed through unmodified.
  if (input.inlineData) {
    aiOpts.inlineData = input.inlineData;
  }
  aiOpts.sanitize = false;

  return Promise.resolve(ai.complete(prompt, aiOpts)).then(function (rawAnswer) {
    var parsed = parseAi(rawAnswer);
    // Normalize shape — guard against missing fields.
    var answer = parsed.answer || (parsed.action ? "" : String(rawAnswer));
    var newHistoryEntry = parsed.action === "replace_text"
      ? "Action Card: Document Modification Proposed."
      : answer;
    var newHistory = capHist((input.history || []).concat([
      { role: "user", content: input.question },
      { role: "model", content: newHistoryEntry },
    ]));
    return {
      raw: rawAnswer,
      action: parsed.action || null,
      target_original: parsed.target_original || "",
      proposed_new: parsed.proposed_new || "",
      explanation: parsed.explanation || "",
      answer: answer,
      citations: Array.isArray(parsed.citations) ? parsed.citations : [],
      followups: Array.isArray(parsed.followups) ? parsed.followups.slice(0, 2) : [],
      history: newHistory,
      overview: String(answer || "").replace(/<[^>]+>/g, "").substring(0, 200),
      provenance: {
        kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
        toolVersion: "v3.1",
        promptVersion: input.modifyMode ? "ask_eli_modify_v1" : "ask_eli_qa_v1",
        model: (ai.currentModel && ai.currentModel()) || null,
        docHash: input.docHash || null,
        timestamp: Date.now(),
      },
    };
  });
}

view.renderChat:
function renderChat(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var initialHistory = opts.history || [];
  var welcomeName = opts.welcomeName || "there";
  var docTypeLabel = opts.docTypeLabel || "document";
  var initialSelection = opts.selectionText || "";
  var initialAttachment = opts.attachment || null; // { name, kind: "pdf"|"file"|"template" }
  var initialScope = opts.scope || "attached"; // "attached" | "both"
  var onSend = opts.onSend || function () {};
  var onBack = opts.onBack || function () {};
  var onClearHistory = opts.onClearHistory || function () {};
  var onAttachOpen = opts.onAttachOpen || function () {};
  var onAttachClear = opts.onAttachClear || function () {};
  var onScopeChange = opts.onScopeChange || function () {};
  var onModifyModeChange = opts.onModifyModeChange || function () {};
  var onImprove = opts.onImprove || null; // optional rewrite-prompt helper
  var onCitationClick = opts.onCitationClick || function () {};
  var onApplyAction = opts.onApplyAction || function () {};
  var onRejectAction = opts.onRejectAction || function () {};
  var onFollowup = opts.onFollowup || null;
  // markdownLite — passed in from init via opts. Falls back to plain
  // escape-with-br when not wired so the view never crashes if the
  // engine helper is missing.
  var markdownLite = opts.markdownLite || function (text) {
    return String(text == null ? "" : text)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/\n/g, "<br>");
  };

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // Compose the root. Layout (top → bottom):
  //   • header bar (back / title / clear)
  //   • scrolling bubble area (chat history)
  //   • scope segmented control (Live / Attached / Both — visible only
  //     when an attachment is present)
  //   • inputbox: textarea with a send button positioned inside its
  //     bottom-right; a small toolbar (Improve / Attach / Draft) anchored
  //     to the bottom-left of the box. The duplicate "Whole document /
  //     Selection · N words" hint that previously sat below the input has
  //     been removed — selection awareness is surfaced inline above the
  //     textarea (selChip) instead.
  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_ae_root _eli3_chat_root";
  root.innerHTML =
    '<div class="_eli3_ae_bar">' +
      '<button class="_eli3_ae_back" title="Back">←</button>' +
      '<div class="_eli3_ae_title">🤖 Ask ELI' +
        '<span class="_eli3_ae_idxdot _eli3_ae_idxdot_busy" id="_eli3_ae_idxdot" title="Indexing the document…"></span>' +
      '</div>' +
      '<button class="_eli3_chat_pintoggle" id="_eli3_chat_pintoggle" title="Hide locate pins (easier copying)">📍</button>' +
      '<button class="_eli3_chat_clear" title="Clear conversation">🧹</button>' +
    '</div>' +
    '<div class="_eli3_chat_scroll" id="_eli3_chat_scroll"></div>' +
    '<div class="_eli3_chat_selchip" id="_eli3_chat_selchip" hidden></div>' +
    '<div class="_eli3_chat_scopebar" id="_eli3_chat_scopebar" hidden>' +
      '<button type="button" class="_eli3_chat_scopeseg" data-scope="live">📄 Live doc</button>' +
      '<button type="button" class="_eli3_chat_scopeseg" data-scope="attached">📎 Attachment</button>' +
      '<button type="button" class="_eli3_chat_scopeseg" data-scope="both">↔ Both</button>' +
    '</div>' +
    '<div class="_eli3_chat_inputbox">' +
      '<textarea class="_eli3_chat_input" id="_eli3_chat_input" rows="2" placeholder="Ask ELI about this document…"></textarea>' +
      '<button type="button" class="_eli3_chat_send" id="_eli3_chat_send" title="Send (Enter)">➤</button>' +
      '<div class="_eli3_chat_toolbar">' +
        '<button type="button" class="_eli3_chat_tool _eli3_chat_improve" id="_eli3_chat_improve" title="Improve prompt">✨ <span class="_eli3_chat_tool_lbl">Improve</span></button>' +
        '<button type="button" class="_eli3_chat_tool _eli3_chat_attach" id="_eli3_chat_attach" title="Attach file or template">📎 <span class="_eli3_chat_tool_lbl _eli3_chat_attach_lbl">Attach</span></button>' +
        '<label class="_eli3_chat_tool _eli3_chat_drafttoggle" id="_eli3_chat_drafttoggle" title="Draft a new clause">' +
          '<input type="checkbox" id="_eli3_chat_draftchk">' +
          '<span>Draft</span>' +
        '</label>' +
      '</div>' +
    '</div>';

  root.querySelector("._eli3_ae_back").onclick = onBack;
  root.querySelector("._eli3_chat_clear").onclick = onClearHistory;
  // Locate-pin toggle — hides the 📍 chips so the user can copy AI text
  // cleanly without grabbing the pin emoji. Pref persists in localStorage
  // so the choice carries across sessions.
  var pinBtn = root.querySelector("#_eli3_chat_pintoggle");
  function _applyPinState(hide) {
    if (hide) root.classList.add("_eli3_chat_hide_pins");
    else      root.classList.remove("_eli3_chat_hide_pins");
    if (pinBtn) {
      pinBtn.textContent = hide ? "📍̶" : "📍";
      pinBtn.title = hide ? "Show locate pins" : "Hide locate pins (easier copying)";
      pinBtn.classList.toggle("_eli3_chat_pintoggle_off", hide);
    }
  }
  var pinHidden = false;
  try {
    pinHidden = (window.localStorage && window.localStorage.getItem("_eli3_chat_hide_pins")) === "1";
  } catch (e) {}
  _applyPinState(pinHidden);
  if (pinBtn) {
    pinBtn.onclick = function () {
      pinHidden = !pinHidden;
      _applyPinState(pinHidden);
      try { window.localStorage.setItem("_eli3_chat_hide_pins", pinHidden ? "1" : "0"); } catch (e) {}
    };
  }

  var scrollEl   = root.querySelector("#_eli3_chat_scroll");
  var selChipEl  = root.querySelector("#_eli3_chat_selchip");
  var scopeBarEl = root.querySelector("#_eli3_chat_scopebar");
  var inputEl    = root.querySelector("#_eli3_chat_input");
  var sendBtn    = root.querySelector("#_eli3_chat_send");
  var attachBtn  = root.querySelector("#_eli3_chat_attach");
  var improveBtn = root.querySelector("#_eli3_chat_improve");
  var draftChk   = root.querySelector("#_eli3_chat_draftchk");

  var defaultPlaceholder = "Ask ELI about this " + docTypeLabel + "…";
  inputEl.placeholder = defaultPlaceholder;

  // ─── State (closure — no window globals) ─────────────────────────
  var state = {
    rewrite: false,                 // selection-chip rewrite toggle
    draft: !!draftChk.checked,      // toolbar draft-clause toggle
    scope: initialScope,
    attachment: initialAttachment,
    selectionText: initialSelection,
    selectionDismissed: false,
    selectionLast: "",
    inFlight: false,
  };

  function _modifyMode() { return state.rewrite || state.draft; }
  function _refreshPlaceholder() {
    if (state.rewrite) inputEl.placeholder = "How do you want to rewrite this clause?";
    else if (state.draft) inputEl.placeholder = "What clause would you like to draft?";
    else inputEl.placeholder = state.selectionText && state.selectionText.length > 4
      ? "Ask ELI about this section…"
      : defaultPlaceholder;
  }
  // _refreshContextHint removed — selection awareness lives in selChip
  // (above textarea) instead of a separate hint pill in the toolbar.
  function _refreshContextHint() { /* no-op kept for backwards compat */ }

  // ─── Bubble factory ──────────────────────────────────────────────
  function _scrollToBottom() {
    requestAnimationFrame(function () { scrollEl.scrollTop = scrollEl.scrollHeight; });
  }
  function _renderBubble(type, html) {
    var wrap = document.createElement("div");
    wrap.className = "_eli3_chat_bubble _eli3_chat_bubble_" + type;
    wrap.innerHTML = html;
    scrollEl.appendChild(wrap);
    _scrollToBottom();
    return wrap;
  }
  function addUserBubble(text) { _renderBubble("user", markdownLite(text)); }
  function addAiBubble(html, citations, followups, hybridNote) {
    var pieces = [];
    if (hybridNote) pieces.push('<div class="_eli3_chat_hybrid">' + hybridNote + '</div>');
    pieces.push(html);
    if (Array.isArray(followups) && followups.length) {
      pieces.push('<div class="_eli3_chat_followups">' +
        followups.slice(0, 2).map(function (f, i) {
          return '<button type="button" class="_eli3_chat_followup" data-followup-i="' + i + '">' +
            '✨ ' + _esc(f) + '</button>';
        }).join("") +
      '</div>');
    }
    var wrap = _renderBubble("ai", pieces.join(""));
    // Wire citation chips (rendered by engine.renderCitations into the html).
    Array.prototype.forEach.call(wrap.querySelectorAll("._eli3_chat_cite"), function (chip) {
      chip.onclick = function () {
        onCitationClick({
          n: chip.getAttribute("data-cite-n"),
          id: chip.getAttribute("data-cite-id"),
          text: chip.getAttribute("data-cite-text"),
        }, chip);
      };
    });
    // Wire follow-up clicks.
    Array.prototype.forEach.call(wrap.querySelectorAll("._eli3_chat_followup"), function (btn, i) {
      btn.onclick = function () {
        var fi = parseInt(btn.getAttribute("data-followup-i"), 10) || 0;
        if (typeof onFollowup === "function") onFollowup(followups[fi]);
        else { inputEl.value = followups[fi] || ""; inputEl.focus(); _doSend(); }
      };
    });
    return wrap;
  }
  function addSystemBubble(html) { _renderBubble("system", html); }
  function showLoader() {
    return _renderBubble("loader",
      '<span class="_eli3_chat_dot"></span>' +
      '<span class="_eli3_chat_dot"></span>' +
      '<span class="_eli3_chat_dot"></span>'
    );
  }
  function removeLoader(node) { if (node && node.parentNode) node.parentNode.removeChild(node); }

  // Action card — replace_text proposal. Reject + Apply (clean) + Apply
  // (with redlines) buttons, plus a redline-preview diff. FROM v2
  // renderActionCard (line 11555).
  function addActionCard(payload) {
    var explanation = payload.explanation || "";
    var orig = payload.target_original || "";
    var prop = payload.proposed_new || "";
    var wrap = document.createElement("div");
    wrap.className = "_eli3_chat_bubble _eli3_chat_bubble_ai _eli3_chat_actioncard";
    wrap.innerHTML =
      '<div class="_eli3_chat_actioncard_head">' +
        '<span>📝 Document modification proposed</span>' +
        '<button type="button" class="_eli3_chat_ac_toggle" data-on="1" title="Toggle Track Changes for apply">📝 Redlines ON</button>' +
      '</div>' +
      (explanation ? '<div class="_eli3_chat_actioncard_explanation">' + _esc(explanation) + '</div>' : "") +
      '<div class="_eli3_chat_actioncard_diff"></div>' +
      '<div class="_eli3_chat_actioncard_actions">' +
        '<button type="button" class="_eli3_chat_actioncard_reject" id="_eli3_chat_ac_reject">Reject</button>' +
        '<button type="button" class="_eli3_chat_actioncard_apply" id="_eli3_chat_ac_apply">Apply</button>' +
      '</div>' +
      '<div class="_eli3_chat_actioncard_status" hidden></div>';
    scrollEl.appendChild(wrap);
    _scrollToBottom();
    var rejectBtn  = wrap.querySelector("#_eli3_chat_ac_reject");
    var applyBtn   = wrap.querySelector("#_eli3_chat_ac_apply");
    var toggleBtn  = wrap.querySelector("._eli3_chat_ac_toggle");
    var diffEl     = wrap.querySelector("._eli3_chat_actioncard_diff");
    var statusEl   = wrap.querySelector("._eli3_chat_actioncard_status");

    // Redlines toggle. ON: diff with red/green. OFF: clean proposed
    // text (no markup) — what the apply will land in the doc.
    var _redlinesOn = true;
    function _paintActionPreview() {
      if (_redlinesOn) {
        diffEl.innerHTML = _renderDiff(orig, prop);
        applyBtn.textContent = "Apply";
      } else {
        diffEl.innerHTML = '<div class="_eli3_chat_diff_clean">' + _esc(prop) + '</div>';
        applyBtn.textContent = "Apply (clean)";
      }
    }
    _paintActionPreview();
    if (toggleBtn) {
      toggleBtn.onclick = function () {
        _redlinesOn = !_redlinesOn;
        toggleBtn.setAttribute("data-on", _redlinesOn ? "1" : "0");
        toggleBtn.textContent = _redlinesOn ? "📝 Redlines ON" : "📄 Redlines OFF";
        _paintActionPreview();
      };
    }
    rejectBtn.onclick = function () {
      onRejectAction(payload);
      wrap.classList.add("_eli3_chat_actioncard_done");
      statusEl.hidden = false;
      statusEl.textContent = "✕ Rejected.";
      applyBtn.disabled = true; rejectBtn.disabled = true;
    };
    applyBtn.onclick = function () {
      applyBtn.disabled = true;
      rejectBtn.disabled = true;
      var orig = applyBtn.textContent;
      applyBtn.textContent = "Applying…";
      Promise.resolve(onApplyAction({
        target_original: payload.target_original,
        proposed_new: payload.proposed_new,
        anchorBookmark: payload.anchorBookmark,
        useRedlines: _redlinesOn,
      })).then(function (result) {
        applyBtn.textContent = "Applied ✓";
        wrap.classList.add("_eli3_chat_actioncard_done");
        statusEl.hidden = false;
        statusEl.textContent = result && result.message
          ? result.message
          : (_redlinesOn ? "✓ Applied with track changes" : "✓ Applied (clean)");
      }).catch(function (err) {
        applyBtn.disabled = false;
        rejectBtn.disabled = false;
        applyBtn.textContent = orig;
        statusEl.hidden = false;
        statusEl.textContent = "⚠ " + (err && err.message || "Apply failed");
        statusEl.className = "_eli3_chat_actioncard_status _eli3_chat_actioncard_status_err";
      });
    };
    return wrap;
  }

  // Word-level diff renderer for action card preview. EXACT v2 port —
  // tokenize via /\S+/g (words only) and use jsdiff (window.Diff loaded
  // via Script Lab Library tab). Same algorithm as legal_risks's
  // computeWordDiffV2 — keeps preview output consistent across tools.
  // CRITICAL: do NOT split keeping whitespace tokens — that produces
  // single-space "change" hunks that render as red+green noise.
  function _renderDiff(oldText, newText) {
    var ot = String(oldText || ""), nt = String(newText || "");
    if (!ot.trim() && !nt.trim()) return '<i class="_eli3_chat_diff_empty">(no preview)</i>';
    if (typeof Diff === "undefined" || typeof Diff.diffArrays !== "function") {
      // Fallback when jsdiff didn't load — show side-by-side strikethrough.
      return '<span class="_eli3_chat_diff_del">' + _esc(ot) + '</span> ' +
             '<span class="_eli3_chat_diff_add">' + _esc(nt) + '</span>';
    }
    var oldTokens = ot.match(/\S+/g) || [];
    var newTokens = nt.match(/\S+/g) || [];
    var parts = Diff.diffArrays(oldTokens, newTokens);
    var html = "";
    parts.forEach(function (p) {
      if (!p.added && !p.removed) {
        p.value.forEach(function (w) { html += _esc(w) + " "; });
      } else if (p.removed) {
        p.value.forEach(function (w) {
          html += '<span class="_eli3_chat_diff_del">' + _esc(w) + '</span> ';
        });
      } else {
        p.value.forEach(function (w) {
          html += '<span class="_eli3_chat_diff_add">' + _esc(w) + '</span> ';
        });
      }
    });
    return html.trim();
  }

  // Translate-result bubble. FROM v2 _runTranslateQuery render.
  function addTranslateBubble(opts) {
    var label = opts.hasTables
      ? '🌐 Translation · Table formatting preserved'
      : '🌐 Translation';
    var body = opts.hasTables
      ? '<div class="_eli3_chat_translate_table">' + (opts.html || "") + '</div>'
      : (opts.html || "");
    return addAiBubble(
      '<div class="_eli3_chat_translate_label">' + label + '</div>' + body
    );
  }

  // ─── Welcome / history replay ────────────────────────────────────
  if (!initialHistory.length) {
    addAiBubble(
      "🤖 <strong>ELI</strong>: Hi " + _esc(welcomeName) + "! What would you like to know about this " + _esc(docTypeLabel) + "?<br>" +
      '<em class="_eli3_chat_welcome_hint">' +
        "I can answer questions, explain clauses, summarize, draft new clauses, translate, and more. " +
        "Highlight text to focus on a section." +
      "</em>"
    );
  } else {
    initialHistory.forEach(function (turn) {
      if (!turn) return;
      if (turn.role === "user") addUserBubble(String(turn.content || ""));
      else if (turn.role === "model") addAiBubble(String(turn.content || ""));
    });
  }

  // ─── Selection chip ──────────────────────────────────────────────
  // Compact pill shown ABOVE the textarea (replaces the old larger chip
  // that lived below). Surfaces:
  //   • word count of the live selection
  //   • a "Rewrite this clause" checkbox (kept inline so the user can
  //     toggle modify mode without leaving the input area)
  //   • a dismiss × that hides the chip without losing the selection
  // The full document is ALWAYS sent as context — the selection just
  // tells the AI which clause to focus on (engine.js: CONTEXTUAL ANALYSIS
  // RULE).
  function setSelection(text) {
    var trimmed = String(text || "").trim();
    state.selectionText = trimmed;
    if (trimmed !== state.selectionLast) {
      state.selectionDismissed = false;
      state.selectionLast = trimmed;
    }
    if (!trimmed || trimmed.length < 4 || state.selectionDismissed) {
      selChipEl.hidden = true;
      selChipEl.innerHTML = "";
      if (state.rewrite) { state.rewrite = false; onModifyModeChange(_modifyMode()); }
      _refreshPlaceholder();
      return;
    }
    selChipEl.hidden = false;
    var words = trimmed.split(/\s+/).length;
    var preview = trimmed.length > 80
      ? (trimmed.substring(0, 80).replace(/\S+$/, "").trim() + "…")
      : trimmed;
    selChipEl.innerHTML =
      '<span class="_eli3_chat_selchip_icon">📍</span>' +
      '<span class="_eli3_chat_selchip_label">Focus · ' + words + ' word' + (words === 1 ? "" : "s") + '</span>' +
      '<span class="_eli3_chat_selchip_preview" title="' + _esc(trimmed) + '">' + _esc(preview) + '</span>' +
      '<label class="_eli3_chat_selchip_rewrite">' +
        '<input type="checkbox" id="_eli3_chat_rewritechk"' + (state.rewrite ? " checked" : "") + '>' +
        '<span>Rewrite</span>' +
      '</label>' +
      '<button type="button" class="_eli3_chat_selchip_dismiss" title="Dismiss">×</button>';
    var dismissBtn = selChipEl.querySelector("._eli3_chat_selchip_dismiss");
    if (dismissBtn) dismissBtn.onclick = function () {
      state.selectionDismissed = true;
      selChipEl.hidden = true;
      _refreshPlaceholder();
    };
    var rewriteChk = selChipEl.querySelector("#_eli3_chat_rewritechk");
    if (rewriteChk) rewriteChk.onchange = function () {
      state.rewrite = rewriteChk.checked;
      _refreshPlaceholder();
      onModifyModeChange(_modifyMode());
    };
    _refreshPlaceholder();
  }
  setSelection(initialSelection);

  // ─── Attach button + scope bar ───────────────────────────────────
  // Attach button: emoji + "Attach" word in the toolbar; turns into a
  // chip-with-✕ when an attachment is present so the user can detach
  // by clicking again.
  // Scope bar: visible only when an attachment is present. Three-way
  // segmented toggle (Live / Attached / Both) replaces the old two-state
  // bar. Default = "both" so the AI sees both contexts unless the user
  // narrows it.
  function setAttachment(att) {
    state.attachment = att || null;
    if (att) {
      attachBtn.classList.add("_eli3_chat_attach_on");
      var name = att.name || "attached";
      var truncName = name.length > 18 ? name.substring(0, 16) + "…" : name;
      attachBtn.innerHTML = '📎 <span class="_eli3_chat_attach_lbl">' + _esc(truncName) + '</span> <span class="_eli3_chat_attach_x">✕</span>';
      attachBtn.title = "Click to detach: " + name;
      scopeBarEl.hidden = false;
    } else {
      attachBtn.classList.remove("_eli3_chat_attach_on");
      attachBtn.innerHTML = '📎 <span class="_eli3_chat_attach_lbl">Attach</span>';
      attachBtn.title = "Attach file or template";
      scopeBarEl.hidden = true;
    }
  }
  function setScope(scope) {
    var s = String(scope || "");
    if (s !== "live" && s !== "attached" && s !== "both") s = "both";
    state.scope = s;
    Array.prototype.forEach.call(scopeBarEl.querySelectorAll("._eli3_chat_scopeseg"), function (seg) {
      var active = seg.getAttribute("data-scope") === state.scope;
      seg.classList.toggle("_eli3_chat_scopeseg_active", active);
    });
  }
  setAttachment(initialAttachment);
  setScope(initialScope);

  attachBtn.onclick = function () {
    if (state.attachment) onAttachClear();
    else onAttachOpen();
  };
  Array.prototype.forEach.call(scopeBarEl.querySelectorAll("._eli3_chat_scopeseg"), function (seg) {
    seg.onclick = function () {
      var s = seg.getAttribute("data-scope");
      setScope(s);
      onScopeChange(s);
    };
  });

  // ─── Draft toggle ────────────────────────────────────────────────
  draftChk.onchange = function () {
    state.draft = draftChk.checked;
    _refreshPlaceholder();
    onModifyModeChange(_modifyMode());
  };

  // ─── Improve button ──────────────────────────────────────────────
  improveBtn.onclick = function () {
    if (!onImprove) return;
    var current = String(inputEl.value || "").trim();
    if (!current) return;
    improveBtn.disabled = true;
    improveBtn.textContent = "⏳";
    Promise.resolve(onImprove(current)).then(function (improved) {
      improveBtn.textContent = "✨";
      improveBtn.disabled = false;
      if (improved) inputEl.value = improved;
    }).catch(function () {
      improveBtn.textContent = "✨";
      improveBtn.disabled = false;
    });
  };

  // ─── Send ────────────────────────────────────────────────────────
  function _doSend() {
    if (state.inFlight) return;
    var question = String(inputEl.value || "").trim();
    if (!question) return;
    state.inFlight = true;
    inputEl.value = "";
    inputEl.style.height = "";
    sendBtn.disabled = true;
    addUserBubble(question);
    var loader = showLoader();

    // Snapshot mode flags BEFORE we reset them — caller decides how to
    // route based on these.
    var sendCtx = {
      modifyMode: _modifyMode(),
      rewrite: state.rewrite,
      draft: state.draft,
      scope: state.scope,
      hasAttachment: !!state.attachment,
      selectionText: state.selectionText,
    };

    Promise.resolve(onSend(question, sendCtx)).then(function (result) {
      removeLoader(loader);
      // Reset modify toggles after each AI response (FROM v2 line 7601).
      _resetModifyToggles();
      if (!result) return;
      if (result.action === "replace_text") {
        addActionCard({
          target_original: result.target_original,
          proposed_new: result.proposed_new,
          explanation: result.explanation,
          anchorBookmark: result.anchorBookmark,
        });
      } else if (result.translate) {
        addTranslateBubble(result.translate);
      } else {
        addAiBubble(result.answer || "", result.citations, result.followups, result.hybridNote);
      }
    }).catch(function (err) {
      removeLoader(loader);
      _resetModifyToggles();
      var msg = (err && err.message) || "Unknown error";
      if (/abort|cancel/i.test(msg)) addSystemBubble("⏹️ Request cancelled.");
      else addSystemBubble('❌ Error: <code>' + _esc(msg) + '</code>');
    }).then(function () {
      state.inFlight = false;
      sendBtn.disabled = false;
      inputEl.focus();
    });
  }
  function _resetModifyToggles() {
    state.rewrite = false;
    state.draft = false;
    if (draftChk) draftChk.checked = false;
    var rewriteChk = root.querySelector("#_eli3_chat_rewritechk");
    if (rewriteChk) rewriteChk.checked = false;
    _refreshPlaceholder();
    onModifyModeChange(false);
  }
  sendBtn.onclick = _doSend;

  // Enter sends; Shift+Enter newline. Auto-grow up to manualHeight or
  // 120px (whichever is larger) — manual resize handle (below) lets
  // power users drag for more room. FROM v2 line 7474.
  inputEl.addEventListener("keydown", function (e) {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); _doSend(); }
  });
  inputEl.addEventListener("input", function () {
    var manual = parseInt(inputEl.dataset.manualHeight || "0", 10) || 0;
    var floor = Math.max(manual, 36);
    inputEl.style.height = "auto";
    inputEl.style.height = Math.max(floor, Math.min(inputEl.scrollHeight, 500)) + "px";
  });

  // ─── Manual resize handle ────────────────────────────────────────
  // FROM v2 line 7456-7472. Dragging the handle adjusts textarea height
  // and stashes the manual floor in dataset.manualHeight so auto-grow
  // respects the user's preferred minimum. Document-level listeners are
  // captured into refs so onBack can remove them — otherwise they leak
  // across pane navigations bound to a closed-over inputEl.
  var resizeHandle = document.createElement("div");
  resizeHandle.className = "_eli3_chat_resize_handle";
  resizeHandle.title = "Drag to resize";
  inputEl.parentNode.insertBefore(resizeHandle, inputEl);
  var resizing = false, startY = 0, startH = 0;
  resizeHandle.addEventListener("mousedown", function (e) {
    resizing = true;
    startY = e.clientY;
    startH = inputEl.offsetHeight;
    document.body.style.cursor = "ns-resize";
    e.preventDefault();
  });
  function _onMouseMove(e) {
    if (!resizing) return;
    var dy = startY - e.clientY;
    var next = Math.max(36, Math.min(500, startH + dy));
    inputEl.style.height = next + "px";
    inputEl.dataset.manualHeight = String(next);
  }
  function _onMouseUp() {
    if (resizing) { resizing = false; document.body.style.cursor = ""; }
  }
  document.addEventListener("mousemove", _onMouseMove);
  document.addEventListener("mouseup", _onMouseUp);
  // Wrap onBack so we tear down listeners + the unsub fires.
  var origOnBack = onBack;
  onBack = function () {
    try { document.removeEventListener("mousemove", _onMouseMove); } catch (e) {}
    try { document.removeEventListener("mouseup", _onMouseUp); } catch (e) {}
    try { origOnBack(); } catch (e) {}
  };
  root.querySelector("._eli3_ae_back").onclick = onBack;

  mount.appendChild(root);

  // Public surface init can call.
  return {
    setSelection: setSelection,
    setAttachment: setAttachment,
    setScope: setScope,
    setDocType: function (label) {
      docTypeLabel = label || "document";
      defaultPlaceholder = "Ask ELI about this " + docTypeLabel + "…";
      _refreshPlaceholder();
    },
    addUserBubble: addUserBubble,
    addAiBubble: addAiBubble,
    addSystemBubble: addSystemBubble,
    addActionCard: addActionCard,
    addTranslateBubble: addTranslateBubble,
    clearScroll: function () { scrollEl.innerHTML = ""; },
    focusInput: function () { inputEl.focus(); },
  };
}

// ─── Attach modal ────────────────────────────────────────────────────
// FROM v2 buildSourceMenuDialog. Two-tab modal: Upload File / Saved
// Templates. Uses showEliDialog as the host. opts.templates is an array
// of {id, label, content, library, category} from the templates store.

view.renderAttachDialog:
function renderAttachDialog(opts) {
  if (typeof showEliDialog !== "function") {
    if (typeof showToast === "function") showToast("Dialog primitive missing", "err");
    return;
  }
  var templates = opts.templates || [];
  var onPickFile = opts.onPickFile || function () {};
  var onPickTemplate = opts.onPickTemplate || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // Group templates by library / agreementType.
  var grouped = {};
  templates.forEach(function (t) {
    if (!t || !t.id || String(t.id).charAt(0) === "_") return;
    var lib = t.library || t.category || t.agreementType || "Library";
    if (!grouped[lib]) grouped[lib] = [];
    grouped[lib].push(t);
  });

  // 2026-05-13 follow-up: saved templates COLLAPSED by default to keep
  // the dialog short. Affordance comes from a styled "click-to-expand"
  // summary (chevron + label + count badge + hover state — see
  // style.css `._eli3_chat_attach_group summary`).
  var groupHtml = Object.keys(grouped).sort().map(function (lib) {
    var items = grouped[lib];
    return '<details class="_eli3_chat_attach_group">' +
      '<summary>' +
        '<span class="_eli3_chat_attach_chev" aria-hidden="true">▸</span>' +
        '<span class="_eli3_chat_attach_grouplbl">' + _esc(lib) + '</span>' +
        '<span class="_eli3_chat_attach_count">' + items.length + '</span>' +
        '<span class="_eli3_chat_attach_hint">Click to expand</span>' +
      '</summary>' +
      '<div class="_eli3_chat_attach_items">' +
        items.map(function (t) {
          var name = t.label || t.name || t.id;
          return '<button type="button" class="_eli3_chat_attach_item" data-tpl-id="' + _esc(t.id) + '" title="Click to attach this template">' +
            '<span class="_eli3_chat_attach_item_icon">📄</span>' +
            '<span class="_eli3_chat_attach_item_name">' + _esc(name) + '</span>' +
            '<span class="_eli3_chat_attach_item_action">Attach →</span>' +
          '</button>';
        }).join("") +
      '</div>' +
    '</details>';
  }).join("");

  var bodyHtml =
    '<div class="_eli3_chat_attach_body">' +
      '<div class="_eli3_chat_attach_section">' +
        '<div class="_eli3_chat_attach_secthead">📁 Upload File</div>' +
        '<label class="_eli3_chat_attach_drop" for="_eli3_chat_attach_file">' +
          '<div class="_eli3_chat_attach_drop_icon">📎</div>' +
          '<div class="_eli3_chat_attach_drop_title">Click to choose a file or drop one here</div>' +
          '<div class="_eli3_chat_attach_drop_sub">PDF stays inline · DOCX/TXT extract to text · up to 5 MB</div>' +
        '</label>' +
        '<input type="file" id="_eli3_chat_attach_file" ' +
          'accept=".pdf,application/pdf,' +
                  '.docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document,' +
                  '.txt,text/plain" ' +
          'hidden>' +
      '</div>' +
      (templates.length
        ? '<div class="_eli3_chat_attach_section">' +
            '<div class="_eli3_chat_attach_secthead">📚 Saved Templates</div>' +
            groupHtml +
          '</div>'
        : '<div class="_eli3_chat_attach_section _eli3_chat_attach_empty">No saved templates. Use Build Draft → Templates to add some.</div>') +
    '</div>';

  showEliDialog({
    variant: "info",
    tier: "premium",
    dialogClass: "_eli3_dialog_wide _eli3_chat_attach_dialog",
    icon: "📎",
    title: "Attach to chat",
    body: bodyHtml,
    secondary: { label: "Cancel" },
    onMount: function (overlay) {
      var fileInp = overlay.querySelector("#_eli3_chat_attach_file");
      if (fileInp) fileInp.onchange = function (e) {
        var f = e.target.files && e.target.files[0];
        if (!f) return;
        onPickFile(f);
        if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
      };
      Array.prototype.forEach.call(overlay.querySelectorAll("[data-tpl-id]"), function (btn) {
        btn.onclick = function () {
          var id = btn.getAttribute("data-tpl-id");
          var t = templates.find(function (tt) { return String(tt.id) === id; });
          if (t) onPickTemplate(t);
          if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
        };
      });
    },
  });
}

// renderDropZoneJumper — FROM v2 showEliDropZoneJumper (line 11726).
// Top-of-pane overlay that asks the user to position their cursor in
// Word, then click "Insert clause" to drop the AI-drafted text at that
// cursor. Used by Draft mode when the AI returns a `replace_text`-style
// action card with NO target_original (pure draft, no clause to replace).

view.renderDropZoneJumper:
function renderDropZoneJumper(opts) {
  var htmlContent = opts.htmlContent || "";
  var mode = opts.mode || "draft";
  var noRedlines = !!opts.noRedlines;
  var onInsert = opts.onInsert || function () {};
  var onCancel = opts.onCancel || function () {};

  var overlay = document.createElement("div");
  overlay.className = "_eli3_chat_dropzone_overlay";
  var msg = (mode === "rewrite")
    ? "Select clause to replace, then click Insert clause."
    : "Place cursor where you want to insert the clause, then click Insert clause.";
  overlay.innerHTML =
    '<div class="_eli3_chat_dropzone_btnrow">' +
      '<button type="button" class="_eli3_chat_dropzone_cancel">Cancel</button>' +
      '<button type="button" class="_eli3_chat_dropzone_insert">⬇️ Insert clause</button>' +
    '</div>' +
    '<div class="_eli3_chat_dropzone_msg">' + msg + '</div>';
  document.body.appendChild(overlay);
  var cancelBtn = overlay.querySelector("._eli3_chat_dropzone_cancel");
  var insertBtn = overlay.querySelector("._eli3_chat_dropzone_insert");
  cancelBtn.onclick = function () {
    if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
    onCancel();
  };
  insertBtn.onclick = function () {
    insertBtn.disabled = true;
    insertBtn.textContent = "Dropping…";
    Promise.resolve(onInsert({ htmlContent: htmlContent, noRedlines: noRedlines })).then(function () {
      if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
    }).catch(function () {
      insertBtn.disabled = false;
      insertBtn.textContent = "Error — try again";
    });
  };
  return {
    close: function () { if (overlay.parentNode) overlay.parentNode.removeChild(overlay); },
  };
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["ask_eli"];
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var analyze               = efns.analyze;
  var buildAskEliPrompt     = efns.buildAskEliPrompt;
  var buildTranslatePrompt  = efns.buildTranslatePrompt;
  var buildAttachmentPrefix = efns.buildAttachmentPrefix;
  var capHistory            = efns.capHistory;
  var parseAiResponse       = efns.parseAiResponse;
  var renderCitations       = efns.renderCitations;
  var isTranslateRequest    = efns.isTranslateRequest;
  var cleanDocHtml          = efns.cleanDocHtml;
  var markRedlinesInOoxml   = efns.markRedlinesInOoxml;
  var classifyAuthorsHeuristic = efns.classifyAuthorsHeuristic;
  var computeWordDiff       = efns.computeWordDiff;
  var markdownLite          = efns.markdownLite;
  var renderChat            = vfns.renderChat;
  var renderAttachDialog    = vfns.renderAttachDialog;
  var renderDropZoneJumper  = vfns.renderDropZoneJumper;
  if (!analyze || !buildAskEliPrompt || !capHistory || !parseAiResponse || !renderChat) {
    eli.log.event("tool", "ask_eli_load_failed", {
      hasAnalyze: !!analyze, hasBuild: !!buildAskEliPrompt, hasCap: !!capHistory,
      hasParse: !!parseAiResponse, hasView: !!renderChat,
    });
    return;
  }

  // ─── Per-doc chat history — SESSION-SCOPED (Batch 7 follow-up
  //     2026-05-11) ─────────────────────────────────────────────
  // Chat history was previously persisted to IDB (config store, key
  // `_chat_history_<docHash>`). User feedback: chat carrying across
  // document reloads / kernel reloads is unwanted. Now ephemeral —
  // ctx.history holds the history in memory for the current session;
  // mounting the chat panel always starts empty.
  //
  // _writeHistory is a no-op (no IDB writes anywhere). _readHistory
  // always returns []. _clearHistory is preserved as a hook the UI
  // "Clear chat" button still calls; a no-op IDB delete is harmless.
  //
  // One-time cleanup at init: sweep any `_chat_history_*` rows left
  // over from past sessions (legacy data). Runs once per kernel boot.
  function _historyKey(docHash) { return "_chat_history_" + (docHash || "default"); }
  function _readHistory(/* docHash */) { return Promise.resolve([]); }
  function _writeHistory(/* docHash, history */) { return Promise.resolve(); }
  function _clearHistory(docHash) {
    return eli.events.safeAsync(eli.storage.delete("config", _historyKey(docHash)), "ask_eli.hist_clear").catch(function () {});
  }
  // Sweep legacy persisted history rows. Best-effort; tolerated failure.
  // getAll returns every row in the config store; we filter by id prefix
  // and delete the chat_history ones. Other config rows (oars sentinel,
  // wrongness toggle, etc.) are untouched.
  (function _sweepLegacyHistory() {
    if (!eli.storage || typeof eli.storage.getAll !== "function") return;
    eli.storage.getAll("config").then(function (rows) {
      if (!Array.isArray(rows)) return;
      var stale = rows.filter(function (r) {
        return r && typeof r.key === "string" && r.key.indexOf("_chat_history_") === 0;
      });
      if (!stale.length) return;
      Promise.all(stale.map(function (r) {
        return eli.storage.delete("config", r.key).catch(function () {});
      })).then(function () {
        eli.log.event("tool", "ask_eli_legacy_history_swept", { count: stale.length });
      });
    }).catch(function () { /* tolerate */ });
  })();

  // ─── Doc hash (matches build_draft._bd_hashContent shape) ────────
  function _hashContent(text) {
    if (!text) return "empty";
    var s = String(text), hash = 0;
    for (var i = 0; i < s.length; i++) {
      hash = ((hash << 5) - hash) + s.charCodeAt(i);
      hash |= 0;
    }
    return "h" + (hash >>> 0).toString(36);
  }

  // ─── AskEliAnchor bookmark sweep ─────────────────────────────────
  // FROM v2 line 7138-7150. On chat entry, sweep any prior session's
  // AskEliAnchor_* bookmarks (they render as visible [ ] in Word when
  // "Show bookmarks" is on).
  function _sweepAnchors() {
    if (!eli.host || !eli.host.runRaw) return Promise.resolve();
    return eli.host.runRaw("ask_eli:anchor_sweep", function (context) {
      var bks = context.document.body.getRange().bookmarks;
      bks.load("items");
      return context.sync().then(function () {
        var items = bks.items || [];
        for (var i = 0; i < items.length; i++) {
          var b = items[i];
          if (b && b.name && b.name.indexOf("AskEliAnchor_") === 0) {
            try { b.delete(); } catch (e) {}
          }
        }
        return context.sync();
      });
    }).catch(function () { /* tolerate */ });
  }

  // ─── Doc + selection read ────────────────────────────────────────
  // Loads body.text + body.getOoxml (for redline detection) +
  // selection.text in one runRaw scope. Pricey on big docs (OOXML can
  // be MB-scale on a 50pp contract), so we cache by docText fingerprint.
  // Selection always re-reads (cheap) so chip + prompt context stay live.
  // Cache invalidates on `eli.host.onDocChange` (handler installed by
  // `_wireSelectionUpdates`).
  // FROM v2 line 11410-11418 (Word.run portion of runChatQuery).
  var _docReadCache = null; // { docHash, docText, ooxml, html }
  function _invalidateDocReadCache() { _docReadCache = null; }
  function _readDocAndSelection() {
    // Selection always re-reads (cheap).
    return eli.host.runRaw("ask_eli:read_sel", function (context) {
      var sel = context.document.getSelection();
      sel.load("text");
      return context.sync().then(function () {
        return String((sel && sel.text) || "");
      });
    }).catch(function () { return ""; }).then(function (selText) {
      // If we have a recent doc cache, only re-read body.text to test
      // for an unchanged hash. body.text alone is much cheaper than
      // OOXML+HTML and is the cheapest fingerprint we can build.
      if (_docReadCache) {
        return eli.host.runRaw("ask_eli:read_text_only", function (context) {
          var body = context.document.body;
          body.load("text");
          return context.sync().then(function () { return String(body.text || ""); });
        }).then(function (docText) {
          var hash = _hashContent(docText);
          if (hash === _docReadCache.docHash) {
            return {
              docText: _docReadCache.docText,
              selectionText: selText,
              docHash: _docReadCache.docHash,
              ooxml: _docReadCache.ooxml,
              html: _docReadCache.html,
            };
          }
          // Hash changed — fall through to full read.
          return _doFullDocRead(selText);
        }).catch(function () { return _doFullDocRead(selText); });
      }
      return _doFullDocRead(selText);
    });
  }
  function _doFullDocRead(selText) {
    return eli.host.runRaw("ask_eli:read_doc", function (context) {
      var body = context.document.body;
      body.load("text");
      var ooxmlResult = body.getOoxml();
      var bodyHtml = body.getHtml();
      return context.sync().then(function () {
        return {
          docText: String(body.text || ""),
          ooxml: String((ooxmlResult && ooxmlResult.value) || ""),
          html: String((bodyHtml && bodyHtml.value) || ""),
        };
      });
    }).then(function (raw) {
      var hash = _hashContent(raw.docText);
      _docReadCache = {
        docHash: hash, docText: raw.docText, ooxml: raw.ooxml, html: raw.html,
        cachedAt: Date.now(),
      };
      return {
        docText: raw.docText,
        selectionText: selText || "",
        docHash: hash,
        ooxml: raw.ooxml,
        html: raw.html,
      };
    }).catch(function (err) {
      eli.log.event("tool", "ask_eli_read_failed", { msg: err && err.message, name: err && err.name });
      // Don't poison docHash with "empty" — preserve any prior real hash
      // so history persistence stays stable across transient read failures.
      var fallbackHash = _docReadCache ? _docReadCache.docHash : "empty";
      return { docText: "", selectionText: selText || "", docHash: fallbackHash, ooxml: "", html: "" };
    });
  }
  // Read selection only (cheaper, used by live-update path).
  function _readSelectionOnly() {
    if (!eli.host || !eli.host.runRaw) return Promise.resolve("");
    return eli.host.runRaw("ask_eli:sel_only", function (context) {
      var sel = context.document.getSelection();
      sel.load("text");
      return context.sync().then(function () { return String(sel.text || ""); });
    }).catch(function () { return ""; });
  }

  // ─── Selection live-update wire ──────────────────────────────────
  // Subscribes to the kernel-level selection observer (eli.selection,
  // Phase 10o) when available. Single shared poller in the kernel feeds
  // all tools so ask_eli doesn't open its own Word.run for selection.
  // Falls back to a hybrid event + active-poll loop on older kernels —
  // event-only was unreliable because Word's onSelectionChanged drops on
  // window blur, Esc-deselect, and mid-edit, leaving the chip stuck
  // showing stale text. The 1.2s timer catches all those misses.
  // Doc-cache invalidation runs on any change (separate concern).
  function _wireSelectionUpdates(view, ctx) {
    var unsubSel = null, unsubDoc = null, pollTimer = null;
    function _applyIfChanged(sel) {
      if (sel === ctx.selectionText) return;
      ctx.selectionText = sel;
      try { view.setSelection(sel); } catch (e) {}
    }
    if (eli.selection && typeof eli.selection.subscribe === "function") {
      unsubSel = eli.selection.subscribe(function (snap) {
        _applyIfChanged((snap && snap.text) || "");
      });
    } else if (eli.host && typeof eli.host.onDocChange === "function") {
      // Legacy hybrid fallback. Event triggers a 250ms-debounced read;
      // the safety-net timer below catches event misses every 1.2s.
      var pending = null;
      function _read() {
        _readSelectionOnly().then(function (sel) { _applyIfChanged(sel || ""); });
      }
      unsubSel = eli.host.onDocChange(function () {
        if (pending) return;
        pending = setTimeout(function () { pending = null; _read(); }, 250);
      });
      pollTimer = setInterval(_read, 1200);
    }
    // Doc-cache invalidation — fires on any selection-or-edit event.
    // Separate from the selection wire because we want to bust the
    // OOXML/HTML cache even when the selection didn't change.
    if (eli.host && typeof eli.host.onDocChange === "function") {
      unsubDoc = eli.host.onDocChange(function () { _invalidateDocReadCache(); });
    }
    return function () {
      try { if (typeof unsubSel === "function") unsubSel(); } catch (e) {}
      try { if (typeof unsubDoc === "function") unsubDoc(); } catch (e) {}
      if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }
    };
  }

  // ─── Insert AskEliAnchor at current selection ────────────────────
  // Returns the bookmark name. FROM v2 line 11425.
  function _insertAnchor() {
    var name = "AskEliAnchor_" + Date.now();
    return eli.host.runRaw("ask_eli:insert_anchor", function (context) {
      var sel = context.document.getSelection();
      try { sel.insertBookmark(name); } catch (e) {}
      return context.sync().then(function () { return name; });
    }).catch(function () { return null; });
  }

  // Delete a single anchor by name. FROM v2 line 11509.
